<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio Business OS V14.6 — Deposit Verification + Won/Project Conversion */
function tuff_beatz_v146_deposit_data($id){$d=get_post_meta((int)$id,'_tb_v146_deposit',true);return is_array($d)?$d:array();}
function tuff_beatz_v146_expected_deposit($id){$p=function_exists('tuff_beatz_v14_proposal_data')?tuff_beatz_v14_proposal_data($id):array();$t=function_exists('tuff_beatz_v14_proposal_totals')?tuff_beatz_v14_proposal_totals($p):array();return (float)($t['deposit']??0);}
function tuff_beatz_v146_conversion_ready($id){$contract=function_exists('tuff_beatz_v145_contract_acceptance')?tuff_beatz_v145_contract_acceptance($id):array();$deposit=tuff_beatz_v146_deposit_data($id);return ($contract['decision']??'')==='accepted'&&($deposit['status']??'')==='verified';}
function tuff_beatz_v146_conversion_box($post){$d=tuff_beatz_v146_deposit_data($post->ID);$o=tuff_beatz_v14_opportunity_data($post->ID);$expected=tuff_beatz_v146_expected_deposit($post->ID);$contract=function_exists('tuff_beatz_v145_contract_acceptance')?tuff_beatz_v145_contract_acceptance($post->ID):array();wp_nonce_field('tb_v146_deposit_'.$post->ID,'tb_v146_deposit_nonce');echo '<p><strong>Contract:</strong> '.esc_html(($contract['decision']??'')==='accepted'?'Accepted':'Not accepted').'</p><p><strong>Expected deposit:</strong> '.esc_html(function_exists('tuff_beatz_money')?tuff_beatz_money($expected):'$'.number_format($expected,2)).'</p><p><label><strong>Deposit status</strong></label><br><select name="tb_v146_deposit_status"><option value="due" '.selected($d['status']??'due','due',false).'>Due</option><option value="pending" '.selected($d['status']??'','pending',false).'>Pending Verification</option><option value="verified" '.selected($d['status']??'','verified',false).'>Verified</option></select></p><p><label><strong>Amount received</strong></label><br><input type="number" min="0" step="0.01" style="width:100%" name="tb_v146_deposit_amount" value="'.esc_attr($d['amount']??$expected).'"></p><p><label><strong>Payment method</strong></label><br><input style="width:100%" name="tb_v146_deposit_method" value="'.esc_attr($d['method']??'').'" placeholder="Card, ACH, Wire..."></p><p><label><strong>Transaction / receipt reference</strong></label><br><input style="width:100%" name="tb_v146_deposit_reference" value="'.esc_attr($d['reference']??'').'"></p><p><label><strong>Payment / checkout URL</strong></label><br><input type="url" style="width:100%" name="tb_v146_deposit_url" value="'.esc_attr($d['payment_url']??'').'"></p>';if($o['linked_request_id'])echo '<p><strong>Production project:</strong> #'.esc_html($o['linked_request_id']).' <a href="'.esc_url(function_exists('tuff_beatz_project_dashboard_url')?tuff_beatz_project_dashboard_url($o['linked_request_id']):get_edit_post_link($o['linked_request_id'])).'">Open</a></p>';}
function tuff_beatz_v146_conversion_metabox(){add_meta_box('tb_v146_deposit','Studio Business OS — Deposit & Conversion','tuff_beatz_v146_conversion_box','tb_opportunity','side','high');}
add_action('add_meta_boxes_tb_opportunity','tuff_beatz_v146_conversion_metabox');
function tuff_beatz_v146_save_deposit($id,$post){if($post->post_type!=='tb_opportunity'||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE))return;if(!isset($_POST['tb_v146_deposit_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_v146_deposit_nonce'])),'tb_v146_deposit_'.$id)||!current_user_can('edit_post',$id))return;$old=tuff_beatz_v146_deposit_data($id);$status=sanitize_key(wp_unslash($_POST['tb_v146_deposit_status']??'due'));if(!in_array($status,array('due','pending','verified'),true))$status='due';$contract=function_exists('tuff_beatz_v145_contract_acceptance')?tuff_beatz_v145_contract_acceptance($id):array();if($status==='verified'&&($contract['decision']??'')!=='accepted')$status='pending';$d=array('status'=>$status,'amount'=>max(0,(float)($_POST['tb_v146_deposit_amount']??0)),'method'=>sanitize_text_field(wp_unslash($_POST['tb_v146_deposit_method']??'')),'reference'=>sanitize_text_field(wp_unslash($_POST['tb_v146_deposit_reference']??'')),'payment_url'=>esc_url_raw(wp_unslash($_POST['tb_v146_deposit_url']??'')),'updated_at'=>current_time('mysql'),'verified_at'=>$status==='verified'?(($old['status']??'')==='verified'?($old['verified_at']??current_time('mysql')):current_time('mysql')):'','verified_by'=>$status==='verified'?get_current_user_id():0);update_post_meta($id,'_tb_v146_deposit',$d);if(($old['status']??'')!==$status&&function_exists('tuff_beatz_v14_add_opportunity_activity'))tuff_beatz_v14_add_opportunity_activity($id,'deposit','Deposit status changed to '.$status);if($status==='verified'){update_post_meta($id,'_tb_v14_stage','deposit-due');update_post_meta($id,'_tb_v14_probability',90);}}
add_action('save_post_tb_opportunity','tuff_beatz_v146_save_deposit',40,2);
function tuff_beatz_v146_find_or_create_client($id){$o=tuff_beatz_v14_opportunity_data($id);if($o['client_id']&&get_userdata($o['client_id']))return (int)$o['client_id'];$email=sanitize_email($o['contact_email']);if($email&&($existing=email_exists($email))){update_post_meta($id,'_tb_v14_client_id',(int)$existing);return (int)$existing;}if(!$email)return 0;$base=sanitize_user(strtolower(strtok($email,'@')),true)?:'client';$username=$base;$i=1;while(username_exists($username))$username=$base.$i++;$uid=wp_insert_user(array('user_login'=>$username,'user_email'=>$email,'user_pass'=>wp_generate_password(24,true,true),'display_name'=>$o['contact_name']?:$email,'role'=>'tb_client'));if(is_wp_error($uid))return 0;update_user_meta($uid,'_tb_industry_type','artist');update_post_meta($id,'_tb_v14_client_id',(int)$uid);return (int)$uid;}
function tuff_beatz_v146_create_project($id){$id=(int)$id;$o=tuff_beatz_v14_opportunity_data($id);if($o['linked_request_id']&&get_post_type($o['linked_request_id'])==='tb_request')return (int)$o['linked_request_id'];if(!tuff_beatz_v146_conversion_ready($id))return new WP_Error('not_ready','Accepted contract and verified deposit are required.');$uid=tuff_beatz_v146_find_or_create_client($id);if(!$uid)return new WP_Error('client_required','A valid client email/account is required.');$p=tuff_beatz_v14_proposal_data($id);$pt=tuff_beatz_v14_proposal_totals($p);$contract=tuff_beatz_v145_contract_data($id);$deposit=tuff_beatz_v146_deposit_data($id);$title=$o['contact_name'].' — '.$o['title'];$request=wp_insert_post(array('post_type'=>'tb_request','post_status'=>'publish','post_title'=>sanitize_text_field($title),'post_author'=>$uid));if(is_wp_error($request)||!$request)return new WP_Error('project_create_failed','Production project could not be created.');$service=sanitize_key($o['service']);if(function_exists('tuff_beatz_services')&&!array_key_exists($service,tuff_beatz_services()))$service='custom';$meta=array('_tb_request_artist'=>$o['contact_name'],'_tb_request_email'=>$o['contact_email'],'_tb_request_service'=>$service?:'custom','_tb_request_industry_type'=>get_user_meta($uid,'_tb_industry_type',true)?:'artist','_tb_request_details'=>$p['summary']??'Converted from Studio Business OS opportunity.','_tb_request_status'=>'approved','_tb_request_submitted_at'=>current_time('mysql'),'_tb_v14_source_opportunity_id'=>$id,'_tb_v14_proposal_version'=>$p['version']??'','_tb_v145_contract_version'=>$contract['version']??'','_tb_v146_conversion_at'=>current_time('mysql'));foreach($meta as $k=>$v)update_post_meta($request,$k,$v);
 $quote=array('number'=>$p['number']??('TB-'.$request),'scope'=>$p['scope']??'','subtotal'=>(float)($p['subtotal']??0),'discount'=>(float)($p['discount']??0),'tax'=>(float)($p['tax']??0),'deposit_percent'=>(float)($p['deposit_percent']??50),'expires'=>$p['expires']??'','payment_url'=>$deposit['payment_url']??'','status'=>'accepted','updated_at'=>current_time('mysql'),'version'=>$p['version']??md5(wp_json_encode($p)));update_post_meta($request,'_tb_quote',$quote);update_post_meta($request,'_tb_contract',array('terms'=>$contract['terms']??'','version'=>$contract['version']??'','updated_at'=>current_time('mysql')));$ca=tuff_beatz_v145_contract_acceptance($id);$accept=array('user_id'=>$uid,'name'=>$ca['name']??$o['contact_name'],'email'=>$ca['email']??$o['contact_email'],'accepted_at'=>$ca['accepted_at']??current_time('mysql'),'quote_version'=>$quote['version'],'contract_version'=>$contract['version']??'','source'=>'Studio Business OS V14.6');update_post_meta($request,'_tb_quote_acceptance',$accept);update_post_meta($request,'_tb_contract_acceptance',$accept);if((float)$deposit['amount']>0)update_post_meta($request,'_tb_payments_v6',array(array('amount'=>(float)$deposit['amount'],'method'=>$deposit['method']?:'Deposit','reference'=>$deposit['reference']??'','status'=>'paid','date'=>$deposit['verified_at']?:current_time('mysql'),'recorded_by'=>(int)($deposit['verified_by']??get_current_user_id()),'source'=>'Studio Business OS V14.6')));if(function_exists('tuff_beatz_sync_payment_status'))tuff_beatz_sync_payment_status($request);update_post_meta($id,'_tb_v14_linked_request_id',$request);update_post_meta($id,'_tb_v14_stage','won');update_post_meta($id,'_tb_v14_probability',100);update_post_meta($id,'_tb_v146_converted_at',current_time('mysql'));update_post_meta($id,'_tb_v146_converted_by',get_current_user_id());if(function_exists('tuff_beatz_v14_add_opportunity_activity'))tuff_beatz_v14_add_opportunity_activity($id,'conversion','Opportunity won and converted to production project #'.$request);return $request;}
function tuff_beatz_v146_convert_action(){ $id=(int)($_POST['opportunity_id']??0);if(!$id||!current_user_can('edit_post',$id))wp_die('Not allowed.',403);check_admin_referer('tb_v146_convert_'.$id,'tb_v146_convert_nonce');$request=tuff_beatz_v146_create_project($id);if(is_wp_error($request)){wp_safe_redirect(add_query_arg('conversion_error',rawurlencode($request->get_error_code()),get_edit_post_link($id,'url')));exit;}wp_safe_redirect(function_exists('tuff_beatz_project_dashboard_url')?tuff_beatz_project_dashboard_url($request):get_edit_post_link($request,'url'));exit;}
add_action('admin_post_tb_v146_convert_project','tuff_beatz_v146_convert_action');
function tuff_beatz_v146_convert_metabox($post){$o=tuff_beatz_v14_opportunity_data($post->ID);if($o['linked_request_id']){echo '<p><strong>Converted.</strong></p><p><a class="button button-primary" href="'.esc_url(function_exists('tuff_beatz_project_dashboard_url')?tuff_beatz_project_dashboard_url($o['linked_request_id']):get_edit_post_link($o['linked_request_id'])).'">Open Production Project</a></p>';return;}if(!tuff_beatz_v146_conversion_ready($post->ID)){echo '<p>Conversion unlocks after contract acceptance and deposit verification.</p>';return;}echo '<p>Ready to create the production project and preserve the approved commercial record.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="tb_v146_convert_project"><input type="hidden" name="opportunity_id" value="'.esc_attr($post->ID).'">';wp_nonce_field('tb_v146_convert_'.$post->ID,'tb_v146_convert_nonce');echo '<button class="button button-primary" type="submit">Mark Won & Create Project</button></form>';}
function tuff_beatz_v146_convert_metabox_register(){add_meta_box('tb_v146_convert','Won → Production','tuff_beatz_v146_convert_metabox','tb_opportunity','side','high');}
add_action('add_meta_boxes_tb_opportunity','tuff_beatz_v146_convert_metabox_register');
